const item = $input.first();
const update = item.json || {};
const callback = update.callback_query || null;
const message = callback?.message || update.message || update.edited_message || {};
const chatId = message.chat?.id ? String(message.chat.id) : "";
const text = callback?.data || message.text || message.caption || "";
const isCallback = Boolean(callback?.id);
const callbackQueryId = callback?.id || "";
const lowerText = String(text || "").trim().toLowerCase();
function cleanMemoryValue(value) {
  return String(value || "").trim().replace(/^[:\-\s]+/, "").replace(/[?.!\s]+$/, "").trim();
}
function parseMemoryCommand(value) {
  const textValue = String(value || "").trim();
  if (!textValue) return { command: "" };
  if (/^(what do you remember|what have i told you to remember|show memories|list memories|list my memories)\??$/i.test(textValue)
    || (/^remind me/i.test(textValue) && /\b(notes? to remember|told you.*remember|everything.*remember)\b/i.test(textValue))) {
    return { command: "recall" };
  }
  const forgetMatch = textValue.match(/^(?:forget|delete memory|remove memory)\s+(.+)$/i);
  if (forgetMatch) {
    const query = cleanMemoryValue(forgetMatch[1]);
    return query ? { command: "forget", query } : { command: "" };
  }
  const rememberMatch = textValue.match(/^(?:remember|note to remember|save memory|memorize)\b\s*:?\s*(.+)$/i);
  if (rememberMatch) {
    const content = cleanMemoryValue(rememberMatch[1]);
    return content ? { command: "remember", content, memoryType: "note" } : { command: "" };
  }
  const politeRemember = textValue.match(/^(?:please\s+)?remember\b\s*(.+)$/i);
  if (politeRemember) {
    const content = cleanMemoryValue(politeRemember[1]);
    return content ? { command: "remember", content, memoryType: "note" } : { command: "" };
  }
  return { command: "" };
}
function cleanBudgetCategory(value) {
  return String(value || "").trim().replace(/^[:\-\s]+/, "").replace(/[?.!\s]+$/, "").trim();
}
function parseBudgetAmount(value) {
  const amount = Number(String(value || "").replace(/,/g, ""));
  return Number.isFinite(amount) && amount > 0 ? amount : 0;
}
function parseBudgetCommand(value) {
  const textValue = String(value || "").trim();
  if (/^(?:list|show|view)\s+(?:my\s+)?budgets\??$/i.test(textValue) || /^what(?:'s| is)?\s+my\s+budgets?\??$/i.test(textValue)) {
    return { command: "list" };
  }
  const deleteMatch = textValue.match(/^(?:delete|remove|clear)\s+(.+?)\s+budget$/i) || textValue.match(/^budget\s+delete\s+(.+)$/i);
  if (deleteMatch) {
    const category = cleanBudgetCategory(deleteMatch[1]);
    return category ? { command: "delete", category } : { command: "" };
  }
  const setMatch =
    textValue.match(/^(?:set|make)\s+(.+?)\s+budget\s+(?:to\s+)?(?:aed\s*)?([\d,]+(?:\.\d{1,2})?)$/i) ||
    textValue.match(/^budget\s+(.+?)\s+(?:to\s+)?(?:aed\s*)?([\d,]+(?:\.\d{1,2})?)$/i) ||
    textValue.match(/^(.+?)\s+budget\s+(?:is\s+|=|to\s+)?(?:aed\s*)?([\d,]+(?:\.\d{1,2})?)$/i);
  if (setMatch) {
    const category = cleanBudgetCategory(setMatch[1]);
    const amount = parseBudgetAmount(setMatch[2]);
    return category && amount ? { command: "set", category, amount } : { command: "" };
  }
  return { command: "" };
}
const memoryCommand = parseMemoryCommand(text);
const budgetCommand = parseBudgetCommand(text);
const pendingCommand = lowerText === "confirm" || lowerText === "/confirm" || lowerText.startsWith("confirm ")
  ? "confirm"
  : (lowerText === "cancel" || lowerText === "/cancel" || lowerText.startsWith("cancel ")
    ? "cancel"
    : (/^(undo|undo last|delete last|remove last)( expense)?$/.test(lowerText) ? "undo_expense" : (memoryCommand.command ? "memory_" + memoryCommand.command : (budgetCommand.command ? "budget_" + budgetCommand.command : ""))));
const createdAt = new Date().toISOString();
const binary = item.binary || {};
const firstBinaryKey = Object.keys(binary)[0];
const media = firstBinaryKey ? binary[firstBinaryKey] : null;
const isVoice = Boolean(message.voice || (media?.mimeType || "").startsWith("audio/"));
const isPhoto = Boolean(message.photo || (media?.mimeType || "").startsWith("image/"));

const schema = {
  type: "object",
  additionalProperties: false,
  properties: {
    intent: { type: "string", enum: ["expense", "receipt", "todo", "reminder", "task_done", "daily_summary", "weekly_summary", "unknown"] },
    date: { type: "string" },
    merchant: { type: "string" },
    amount: { type: "number" },
    currency: { type: "string" },
    category: { type: "string", enum: ["Food", "Transport", "Groceries", "Bills", "Shopping", "Business", "Health", "Entertainment", "Travel", "Trading", "Other"] },
    payment_method: { type: "string" },
    card: { type: "string" },
    notes: { type: "string" },
    task: { type: "string" },
    type: { type: "string", enum: ["todo", "reminder", ""] },
    priority: { type: "string", enum: ["low", "normal", "high", ""] },
    due_at: { type: "string" },
    task_match_text: { type: "string" },
    missing_fields: { type: "array", items: { type: "string" } },
    confidence: { type: "number" }
  },
  required: ["intent", "date", "merchant", "amount", "currency", "category", "payment_method", "card", "notes", "task", "type", "priority", "due_at", "task_match_text", "missing_fields", "confidence"]
};

const systemPrompt = [
  "You are a strict JSON parser for a Telegram personal assistant.",
  "Extract expenses, receipt totals, todos, reminders, task completion commands, and summary requests.",
  "Return only JSON that matches the provided schema. No prose, markdown, comments, or extra keys.",
  "Use Asia/Dubai timezone. Current timestamp: " + createdAt + ".",
  "Default currency is AED.",
  "If the amount, task text, due time, or completion target is missing, include the missing key in missing_fields and keep confidence below 0.7.",
  "For expenses, merchant can be a best guess from context; amount is required. Put specific card/account names in card, for example ADCB Visa, Wio, Mashreq, cash, Apple Pay.",
  "Known debit cards: ADCB Debit, ENBD Debit, DIB Debit, RAK Debit, CBD Debit.",
  "Known credit cards: ADCB Credit, ENBD Credit, DIB Credit, RAK Credit, TABBY Credit.",
  "Recurring payment names: ADCB Credit Card Payment, ENBD Credit Card Payment, DIB Credit Card Payment, RAK Credit Card Payment, TABBY Payment, ETISALAT Payment.",
  "If the user says a bank plus debit or credit, normalize card to the matching known card name. If a new card name is mentioned, preserve it exactly in card so Supabase can auto-add it.",
  "For receipt photos, extract merchant/date/total/currency/category/payment card if visible.",
  "For reminders, due_at must be ISO 8601 if the user gave a due date/time. If not, put due_at empty and include due_at in missing_fields.",
  "For task completion messages like 'done buy printer ink', set intent task_done and task_match_text to the target phrase.",
  "For 'summary today', 'weekly report', or similar, set intent daily_summary or weekly_summary."
].join("\n");

const content = [{ type: "input_text", text: text || (isPhoto ? "Parse this receipt image." : "Parse this Telegram message.") }];
if (media?.data && isPhoto) {
  content.push({
    type: "input_image",
    image_url: "data:" + (media.mimeType || "image/jpeg") + ";base64," + media.data
  });
}

return [{
  json: {
    chatId,
    createdAt,
    source: isVoice ? "telegram_voice" : (isPhoto ? "telegram_photo" : "telegram_text"),
    originalText: text,
    needsTranscription: isVoice,
    pendingCommand,
    memoryCommand,
    budgetCommand,
    isCallback,
    callbackQueryId,
    mediaMimeType: media?.mimeType || "",
    binaryKey: firstBinaryKey || "",
    voiceFileId: message.voice?.file_id || "",
    binaryKey: firstBinaryKey || "",
    voiceFileId: message.voice?.file_id || "",
    binaryKey: firstBinaryKey || "",
    openaiBody: {
      model: "gpt-4.1-mini",
      input: [
        { role: "system", content: [{ type: "input_text", text: systemPrompt }] },
        { role: "user", content }
      ],
      text: {
        format: {
          type: "json_schema",
          name: "assistant_parse",
          strict: true,
          schema
        }
      }
    }
  },
  binary
}];

const response = $input.first().json;
let original = $("Normalize Telegram Input").item.json;
try {
  const voiceInput = $("Apply Voice Transcript").item.json;
  if (voiceInput?.voiceTranscript) original = voiceInput;
} catch (error) {}
let text = response.output_text;
if (!text && Array.isArray(response.output)) {
  for (const output of response.output) {
    for (const content of output.content || []) {
      if (content.type === "output_text" && content.text) text = content.text;
    }
  }
}

let parsed;
try {
  parsed = JSON.parse(text || "{}");
} catch (error) {
  parsed = {
    intent: "unknown",
    notes: "OpenAI returned invalid JSON",
    missing_fields: ["intent"],
    confidence: 0
  };
}

const now = new Date().toISOString();
const intent = parsed.intent || "unknown";
const amount = Number(parsed.amount || 0);
const confidence = Number(parsed.confidence || 0);
const missing = Array.isArray(parsed.missing_fields) ? parsed.missing_fields.filter(Boolean) : [];
if ((intent === "expense" || intent === "receipt") && amount <= 0 && !missing.includes("amount")) missing.push("amount");
if ((intent === "todo" || intent === "reminder") && !String(parsed.task || "").trim() && !missing.includes("task")) missing.push("task");
if (intent === "reminder" && !String(parsed.due_at || "").trim() && !missing.includes("due_at")) missing.push("due_at");
if (intent === "task_done" && !String(parsed.task_match_text || parsed.task || "").trim() && !missing.includes("task_match_text")) missing.push("task_match_text");

const uncertaintyPattern = /\b(maybe|probably|i think|not sure|roughly|around|about|approx|approximately)\b/i;
const requires_confirmation = missing.length === 0 && uncertaintyPattern.test(String(original.originalText || parsed.notes || ""));
const valid = missing.length === 0 && intent !== "unknown";
let confirmation = "";
if (!valid) {
  const human = missing.join(", ") || "details";
  confirmation = "I need a little more info before saving this. Missing: " + human + ".";
} else if (intent === "expense" || intent === "receipt") {
  confirmation = "Saved expense: " + (parsed.merchant || "Unknown merchant") + " " + amount + " " + (parsed.currency || "AED") + " (" + (parsed.category || "Other") + ")" + (parsed.card ? "\nCard: " + parsed.card : "") + (confidence < 0.7 ? "\nLow confidence - please check the sheet." : "");
} else if (intent === "todo") {
  confirmation = "Saved todo: " + parsed.task;
} else if (intent === "reminder") {
  confirmation = "Saved reminder: " + parsed.task + "\nDue: " + parsed.due_at;
} else if (intent === "task_done") {
  confirmation = "I'll mark this done if I find a matching open task: " + (parsed.task_match_text || parsed.task || "");
} else if (intent === "daily_summary" || intent === "weekly_summary") {
  confirmation = "Summary requests are handled by the scheduled summary workflow for now.";
}

return [{
  json: {
    ...parsed,
    intent,
    amount,
    confidence,
    missing_fields: missing,
    requires_confirmation,
    valid,
    chatId: original.chatId,
    originalText: original.originalText,
    source: original.source,
    CreatedAt: now,
    confirmation
  }
}];

return $input.all().map((item) => ({
  json: {
    expense_date: item.json.date || new Date().toISOString().slice(0, 10),
    merchant: item.json.merchant || null,
    amount: Number(item.json.amount || 0),
    currency: item.json.currency || "AED",
    category: item.json.category || "Other",
    payment_method: item.json.payment_method || null,
    card: item.json.card || null,
    notes: item.json.notes || null,
    source: item.json.source || (item.json.intent === "receipt" ? "receipt" : "telegram_text"),
    confidence: item.json.confidence || 0,
    raw_payload: item.json
  }
}));

return $input.all().map((item) => ({
  json: {
    task: item.json.task || item.json.notes || "",
    type: item.json.intent === "reminder" ? "reminder" : "todo",
    status: "open",
    priority: item.json.priority || "normal",
    due_at: item.json.due_at || null,
    notes: item.json.notes || null,
    raw_payload: item.json
  }
}));

const source = $("Parse OpenAI Result").item.json;
const target = String(source.task_match_text || source.task || "").toLowerCase();
const rows = $input.all();
const openRows = rows.filter((item) => String(item.json.status || "").toLowerCase() === "open");
function score(task) {
  const words = target.split(/\s+/).filter(Boolean);
  const value = String(task || "").toLowerCase();
  return words.filter((word) => value.includes(word)).length;
}
let best = null;
let bestScore = 0;
for (const item of openRows) {
  const current = score(item.json.task);
  if (current > bestScore) {
    best = item;
    bestScore = current;
  }
}
if (!best || bestScore === 0) {
  return [{ json: { confirmation: "I could not find a matching open task. Try: done exact task name", skipUpdate: true } }];
}
return [{
  json: {
    id: best.json.id,
    task: best.json.task,
    status: "done",
    completed_at: new Date().toISOString(),
    confirmation: "Marked done: " + best.json.task
  }
}];

return $input.all().map((item) => ({
  json: {
    workflow: "Telegram Personal Assistant - Inbox Supabase",
    chat_id: item.json.chatId || "",
    raw_input: item.json.originalText || "",
    intent: item.json.intent || "unknown",
    parsed_json: item.json,
    status: item.json.valid ? "parsed" : "needs_clarification",
    message: item.json.confirmation || "",
    missing_fields: item.json.missing_fields || [],
    execution_source: item.json.source || "telegram"
  }
}));

const item = $input.first();
const original = $("Normalize Telegram Input").item.json;
const binary = item.binary || {};
const data = binary.data;
const errorMessage = item.json?.error?.message || item.json?.message || "";

if (errorMessage || !data) {
  return [{
    json: {
      ...original,
      source: "telegram_voice",
      voiceProcessingError: true,
      confirmation: "I received your voice note, but I could not download the audio from Telegram. Please resend it or type the message."
    }
  }];
}

data.fileName = "telegram-voice.ogg";
data.fileExtension = "ogg";
data.mimeType = "audio/ogg";
return [{ json: item.json, binary }];

const transcription = $input.first().json || {};
const original = $("Normalize Telegram Input").item.json;
const errorMessage = transcription.error?.message || transcription.message || "";
const transcript = String(transcription.text || "").trim();

if (errorMessage || !transcript) {
  return [{
    json: {
      ...original,
      source: "telegram_voice",
      voiceProcessingError: true,
      voiceTranscript: transcript,
      transcriptionModel: "gpt-4o-mini-transcribe",
      confirmation: "I received your voice note, but I could not transcribe it clearly. Please resend a clearer voice note or type the message."
    }
  }];
}

const openaiBody = JSON.parse(JSON.stringify(original.openaiBody));
const userMessage = openaiBody.input.find((entry) => entry.role === "user");
if (userMessage?.content?.[0]) {
  userMessage.content[0].text = transcript;
}
return [{
  json: {
    ...original,
    source: "telegram_voice",
    originalText: transcript,
    voiceTranscript: transcript,
    transcriptionModel: "gpt-4o-mini-transcribe",
    openaiBody
  }
}];

const pending = $input.first().json;
if (!pending?.id) return [{ json: { skipPending: true, confirmation: "No pending item to confirm." } }];
const payload = pending.payload || {};
if (pending.action_type === "expense" || pending.action_type === "receipt") {
  return [{
    json: {
      pending_id: pending.id,
      target: "expense",
      expense_date: payload.date || new Date().toISOString().slice(0, 10),
      merchant: payload.merchant || null,
      amount: Number(payload.amount || 0),
      currency: payload.currency || "AED",
      category: payload.category || "Other",
      payment_method: payload.payment_method || null,
      card: payload.card || null,
      notes: payload.notes || null,
      source: payload.source || "telegram_pending",
      confidence: payload.confidence || 0,
      raw_payload: payload,
      confirmation: "Confirmed expense: " + (payload.merchant || "Unknown") + " " + Number(payload.amount || 0) + " " + (payload.currency || "AED") + (payload.card ? " using " + payload.card : "")
    }
  }];
}
return [{
  json: {
    pending_id: pending.id,
    target: "task",
    task: payload.task || payload.notes || "",
    type: payload.intent === "reminder" ? "reminder" : "todo",
    status: "open",
    priority: payload.priority || "normal",
    due_at: payload.due_at || null,
    notes: payload.notes || null,
    raw_payload: payload,
    confirmation: "Confirmed task: " + (payload.task || payload.notes || "Task")
  }
}];

