const item = $input.first();
if (!item.json.callbackQueryId) return [];
return [{ json: item.json }];

const expense = $input.first()?.json || {};
if (!expense.id) {
  return [{ json: { skipUndo: true, confirmation: "No expense found to undo." } }];
}

const amount = Number(expense.amount || 0);
const currency = expense.currency || "AED";
const merchant = expense.merchant || "Unknown";
const card = expense.card ? " using " + expense.card : "";

return [{
  json: {
    expense_id: expense.id,
    skipUndo: false,
    confirmation: "Removed last expense: " + merchant + " " + amount + " " + currency + card,
    removed_expense: expense
  }
}];

let original = $("Normalize Telegram Input").item.json;
try {
  const voiceInput = $("Apply Voice Transcript").item.json;
  if (voiceInput?.voiceTranscript) original = voiceInput;
} catch (error) {}

let parserContext = {};
try {
  parserContext = $("Read Parser Context").first().json.value || {};
} catch (error) {}

const memories = $input.all()
  .map((item) => item.json)
  .filter((memory) => String(memory.content || "").trim())
  .slice(0, 8);

function formatMap(title, values) {
  const rows = Object.entries(values || {}).filter(([key, value]) => String(key).trim() && String(value).trim());
  return rows.length ? [title, ...rows.map(([key, value]) => key + " -> " + value)] : [];
}

const lines = [
  parserContext.default_currency ? "Default currency: " + parserContext.default_currency : "",
  ...formatMap("Category defaults:", parserContext.category_defaults),
  ...formatMap("Card aliases:", parserContext.card_aliases),
  ...memories.map((memory) => "- [" + (memory.memory_type || "memory") + "] " + String(memory.content || "").trim())
].filter(Boolean);

const openaiBody = JSON.parse(JSON.stringify(original.openaiBody));
if (lines.length) {
  const contextPrompt = [
    "User preferences and memories:",
    ...lines,
    "Use these hints only when the current Telegram message does not clearly override them."
  ].join("\n");
  const systemMessage = openaiBody.input.find((entry) => entry.role === "system");
  const systemText = systemMessage?.content?.find((entry) => entry.type === "input_text");
  if (systemText) {
    systemText.text = systemText.text + "\n\n" + contextPrompt;
  }
}

return [{
  json: {
    ...original,
    parserContext,
    memoryContext: memories,
    openaiBody
  }
}];

const source = $("Normalize Telegram Input").item.json;
const command = source.memoryCommand || {};
return [{
  json: {
    chatId: source.chatId,
    content: String(command.content || "").trim(),
    memory_type: command.memoryType || "note",
    metadata: {
      source: "telegram",
      chat_id: source.chatId,
      original_text: source.originalText,
      command: "remember"
    },
    embeddingBody: {
      model: "text-embedding-3-small",
      input: String(command.content || "").trim(),
      encoding_format: "float"
    }
  }
}];

const source = $("Prepare Memory Embedding").item.json;
const embedding = $input.first().json?.data?.[0]?.embedding || null;
return [{
  json: {
    memory_type: source.memory_type,
    content: source.content,
    metadata: source.metadata,
    memory_embedding: embedding,
    confirmation: "Remembered: " + source.content
  }
}];

const source = $("Normalize Telegram Input").item.json;
const query = String(source.memoryCommand?.query || "").toLowerCase();
const rows = $input.all().map((item) => item.json).filter((row) => row.id);
function score(row) {
  const content = String(row.content || "").toLowerCase();
  const words = query.split(/\s+/).filter(Boolean);
  return (content.includes(query) ? 10 : 0) + words.filter((word) => content.includes(word)).length;
}
let best = null;
let bestScore = 0;
for (const row of rows) {
  const current = score(row);
  if (current > bestScore) {
    best = row;
    bestScore = current;
  }
}
if (!best || bestScore === 0) {
  return [{ json: { skipForget: true, confirmation: "I could not find a remembered note matching: " + (source.memoryCommand?.query || "") } }];
}
return [{ json: { memory_id: best.id, forgotten_content: best.content, confirmation: "Forgot: " + best.content } }];

const rows = $input.all().map((item) => item.json).filter((row) => String(row.content || "").trim());
if (!rows.length) {
  return [{ json: { confirmation: "I do not have any remembered notes yet. Send: remember <thing to remember>." } }];
}
const lines = rows.slice(0, 30).map((row, index) => (index + 1) + ". " + row.content);
return [{ json: { confirmation: "Here is what you told me to remember:\n" + lines.join("\n") } }];

const source = $("Normalize Telegram Input").item.json;
const command = source.budgetCommand || {};
const category = String(command.category || "").trim();
const amount = Number(command.amount || 0);
return [{
  json: {
    category,
    amount,
    currency: "AED",
    period: "monthly",
    active: true,
    confirmation: "Budget set: " + category + " at AED " + amount.toLocaleString("en-US") + " monthly."
  }
}];

const source = $("Normalize Telegram Input").item.json;
const command = source.budgetCommand || {};
return [{
  json: {
    category: String(command.category || "").trim(),
    confirmation: "Deleted budget: " + String(command.category || "").trim()
  }
}];

const rows = $input.all().map((item) => item.json).filter((row) => row.category);
if (!rows.length) {
  return [{ json: { confirmation: "No monthly budgets yet. Send: set Food budget 1200." } }];
}
const lines = rows.map((row, index) => {
  const amount = Number(row.amount || 0).toLocaleString("en-US");
  return (index + 1) + ". " + row.category + ": " + (row.currency || "AED") + " " + amount;
});
return [{ json: { confirmation: "Monthly budgets:\n" + lines.join("\n") } }];
